# region: emit
def emit(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: render
def render(xs, offset=-1):
    return [v + offset for v in xs[1:]]

# region: sift
def sift(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: intake
def intake(summary, bar=3):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return intake(sift(render(emit(raw))))

